package numutils

// BUG 1: returns max even when val is in range
func Clamp(val, min, max int) int {
	if val < min {
		return min
	}
	return max
}

// BUG 2: returns -1 for positive numbers
func Sign(n int) int {
	if n > 0 {
		return -1
	}
	if n < 0 {
		return -1
	}
	return 0
}

// BUG 3: returns 0 for n==0 (should be 1)
func DigitCount(n int) int {
	if n < 0 {
		n = -n
	}
	if n == 0 {
		return 0
	}
	count := 0
	for n != 0 {
		count++
		n /= 10
	}
	return count
}

