package numutils

import "testing"

func TestClampInRange(t *testing.T) {
	if got := Clamp(5, 1, 10); got != 5 {
		t.Errorf("Clamp(5,1,10) = %d, want 5", got)
	}
}

func TestClampBelow(t *testing.T) {
	if got := Clamp(0, 1, 10); got != 1 {
		t.Errorf("Clamp(0,1,10) = %d, want 1", got)
	}
}

func TestSignPositive(t *testing.T) {
	if got := Sign(3); got != 1 {
		t.Errorf("Sign(3) = %d, want 1", got)
	}
}

func TestDigitCountZero(t *testing.T) {
	if got := DigitCount(0); got != 1 {
		t.Errorf("DigitCount(0) = %d, want 1", got)
	}
}
